 dict(id='DocTer',stem='docter',year=2022,doi='10.1145/3533767.3534220',arxiv_version='2109.01002v4',version_relation='2024 arXiv revision of ISSTA 2022 paper; publisher PDF byte identity unverified',full_text_review='PASS',sections={'method':'2.1-2.5, PDF pp. 3-8','implementation_evaluation':'3-4, PDF pp. 8-11','limits':'5, PDF pp. 11-12'},constraint_origin='Documentation dependency parses and rules learned from manually annotated abstract constraints',analysis='Offline extraction followed by valid/invalid input generation and concrete testing',wrapper='Test harness, not demonstrated deployment enforcement wrapper',complete_model_resource_getter_decoder_join='NOT_DEMONSTRATED_IN_REVIEWED_METHOD_OR_EVALUATION',implementation_status='Implemented and evaluated as reported, not reproduced by this audit',our_increment='Consumer/artifact relation is a candidate distinction, not generic constraint extraction'),
