for r in rows:
 p=ROOT/'sources'/(r['stem']+'.pdf');r.update(pdf_path=str(p),pdf_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),text_path=str(p.with_name(r['stem']+'-reading.txt')))
 c=json.loads((ROOT/'sources'/(r['stem']+'-crossref.json')).read_text())['message']
 r.update(title=c['title'][0],venue=c.get('container-title'),crossref_publication_date=c.get('published'))
 if r['arxiv_version']:r['pinned_pdf_url']='https://arxiv.org/pdf/'+r['arxiv_version']
 else:r['recorded_original_pdf_url']='https://link.springer.com/content/pdf/10.1007/s10664-025-10711-4.pdf'
