for name in ['dara']:
 old=pathlib.Path('/workspace/metadata-contract-paper/sources/dara-paper.pdf');assert hashlib.sha256(old.read_bytes()).hexdigest()==next(r['pdf_sha256'] for r in rows if r['stem']==name)
manifest=[]
for p in sorted(ROOT.rglob('*')):
 if p.is_file() and p.name!='SHA256SUMS':manifest.append(hashlib.sha256(p.read_bytes()).hexdigest()+'  '+str(p.relative_to(ROOT)))
(ROOT/'SHA256SUMS').write_text('\n'.join(manifest)+'\n')
print(json.dumps({'papers':len(rows),'sealed_files':len(manifest),'old_dara_unchanged':True}))
